B.bdR=new A.a9(B.u,B.asH,null,"La yema est\xe1 firme de lado a lado.",B.as1,B.j,B.j,"Sin pelar, hasta 5 d\xedas en la nevera.","Tostada integral y fruta.",B.t)
B.aI9=s(["Airfryer","Colador","Pa\xf1o limpio","Bol"],t.s)
